// Se llama cuando el script se agrega a un GameObject por primera vez
// O cuando se hace Reset desde el menú contextual del componente
void Reset()
{
    // Establece valores por defecto razonables
    velocidad = 5f;
    vida = 100;
}

// Se llama en el Editor cada vez que se modifica un campo en el Inspector
// También se llama al cargar la escena
void OnValidate()
{
    // Fuerza valores en rangos válidos
    vida = Mathf.Max(1, vida);     // La vida nunca puede ser menor a 1
    radio = Mathf.Abs(radio);      // El radio no puede ser negativo
}

// Se llama cuando la aplicación pausa (dentro del Editor o en builds)
void OnApplicationPause(bool pauseStatus)
{
    if (pauseStatus) GuardarProgreso();
}

// Se llama en TODOS los frames del Editor para dibujar ayudas visuales
// Los Gizmos se ven en la Scene View, NO en el juego final
void OnDrawGizmos()
{
    Gizmos.color = Color.red;
    Gizmos.DrawWireSphere(transform.position, radioDeAtaque);
}

// Solo se dibuja cuando el objeto está SELECCIONADO en el Editor
void OnDrawGizmosSelected()
{
    Gizmos.color = Color.yellow;
    // Dibuja el radio de patrulla solo cuando seleccionas el enemigo
    Gizmos.DrawWireSphere(transform.position, radioDePatrulla);
}

// Ejemplos de Gizmos útiles:
// Gizmos.DrawLine(puntoA, puntoB)  → línea entre dos puntos
// Gizmos.DrawRay(origen, dirección) → rayo visual
// Gizmos.DrawCube(centro, tamaño)  → caja

